/** void DrawBattlerOnBg(int bgId, u8 x, u8 y, u8 battlerPosition, u8 paletteId, u8 *tiles, u16 *tilemap, u16 tilesOffset) */
export function DrawBattlerOnBg(bgId: any, x: any, y: any, battlerPosition: any, paletteId: any, tiles: any, tilemap: any, tilesOffset: any): any {
  let i, j;
      let battler: any = GetBattlerAtPosition(battlerPosition);
      let offset: any = tilesOffset;
      CpuCopy16(gMonSpritesGfxPtr.sprites.ptr[battlerPosition] + BG_SCREEN_SIZE * gBattleMonForms[battler], tiles, BG_SCREEN_SIZE);
      LoadBgTiles(bgId, tiles, 0x1000, tilesOffset);
      for (i = y; i < y + 8; i++)
      {
          for (j = x; j < x + 8; j++)
          {
              tilemap[i * 32 + j] = offset | (paletteId << 12);
              offset++;
          }
      }
      LoadBgTilemap(bgId, tilemap, BG_SCREEN_SIZE, 0);
}

